import { PCT_ENCODED_SRC } from "./rfc-3986.js";
import { IPRIVATE_SRC, UCSCHAR_SRC } from "./rfc-3987.js";
//#region src/utils/rfc-6570.ts
const LITERALS_SRC = `(?:[${`!#$&-;=?-[\\]_a-z~${UCSCHAR_SRC}${IPRIVATE_SRC}`}]|${PCT_ENCODED_SRC})`;
const VARCHAR_SRC = `(?:[A-Za-z0-9_]|${PCT_ENCODED_SRC})`;
const VARSPEC_SRC = `${`${VARCHAR_SRC}(?:\\.?${VARCHAR_SRC})*`}(?::[1-9][0-9]{0,3}|\\*)?`;
const EXPRESSION_SRC = `\\{[+#./;?&=,!@|]?${VARSPEC_SRC}(?:,${VARSPEC_SRC})*\\}`;
const URI_TEMPLATE_REGEX = new RegExp(`^(?:${LITERALS_SRC}|${EXPRESSION_SRC})*$`, "u");
/**
* Tests a string against RFC 6570 §2 `URI-Template`, with Errata 6937 (Verified) applied.
*
* Accepts the empty string — `*( literals / expression )` admits zero repetitions.
*/
const isValidUriTemplate = (value) => URI_TEMPLATE_REGEX.test(value);
//#endregion
export { isValidUriTemplate };
